// Copies content/ into mobile/src/data (Metro cannot import files outside mobile/)
// and writes mobile/src/data/lessons.ts with one static require per lesson.
// Run with: node tools/build-content.mjs   (never edit the generated files by hand)
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync, copyFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const CONTENT = join(ROOT, 'content');
const DATA = join(ROOT, 'mobile', 'src', 'data');
const LEVELS = ['A1', 'A2', 'B1'];

rmSync(join(DATA, 'lessons'), { recursive: true, force: true });
mkdirSync(DATA, { recursive: true });
copyFileSync(join(CONTENT, 'curriculum.json'), join(DATA, 'curriculum.json'));

const lines = [
  '// AUTO-GENERATED by tools/build-content.mjs. Do not edit by hand.',
  "import type { Curriculum, Lesson, Level } from '../types';",
  "import curriculum from './curriculum.json';",
  '',
  'export const curriculumData = curriculum as Curriculum;',
  '',
  'export const lessons: Record<Level, Record<string, Lesson>> = {',
];

for (const level of LEVELS) {
  const dir = join(CONTENT, 'lessons', level);
  const files = existsSync(dir) ? readdirSync(dir).filter((f) => f.endsWith('.json')).sort() : [];
  lines.push(`  ${level}: {`);
  for (const file of files) {
    const slug = file.replace(/\.json$/, '');
    const outDir = join(DATA, 'lessons', level);
    mkdirSync(outDir, { recursive: true });
    copyFileSync(join(dir, file), join(outDir, file));
    lines.push(`    '${slug}': require('./lessons/${level}/${file}') as Lesson,`);
  }
  lines.push('  },');
}
lines.push('};', '');
writeFileSync(join(DATA, 'lessons.ts'), lines.join('\n'));
console.log(`Wrote ${join('mobile', 'src', 'data', 'lessons.ts')}`);
